const HOME_V23_JS="/* Tiki-Data v23 — SportAPI.ai only. No legacy API and no client-side secrets. */\n(()=>{'use strict';\nconst $=id=>document.getElementById(id);\nif(!$('featuredContent'))return;\nconst esc=x=>String(x??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;','\\'':'&#39;'}[c]));\nconst initial=x=>String(x||'FC').trim().split(/\\s+/).filter(w=>!/(?:FC|CF|AC|SC|AFC)$/i.test(w)).slice(0,2).map(x=>x[0]||'').join('').slice(0,3).toUpperCase()||'FC';\nconst safeLogo=x=>typeof x==='string'&&/^\\/api\\/logo\\/team\\/\\d{1,13}\\?sig=[0-9a-f]{64}$/.test(x)?x:null;\nconst num=n=>typeof n==='number'&&Number.isFinite(n)?n:null;\nconst pct=n=>num(n)===null?'—':n.toLocaleString('el-GR',{maximumFractionDigits:1})+'%';\nconst fmtDate=new Intl.DateTimeFormat('el-GR',{weekday:'short',day:'numeric',month:'short'});\nconst fmtTime=new Intl.DateTimeFormat('el-GR',{hour:'2-digit',minute:'2-digit',hour12:false});\nconst isLive=m=>['LIVE','1H','2H','HT','ET','BREAK'].includes(m?.status);\nconst isDone=m=>['FT','AET','PEN','FINISHED','FULL_TIME'].includes(m?.status);\nfunction crest(m,side){const name=m[side]||'Ομάδα';const url=safeLogo(m.logos?.[side]);\n  return '<span class=\"crest fallback\">'+(url?'<img loading=\"lazy\" src=\"'+esc(url)+'\" alt=\"Έμβλημα '+esc(name)+'\" onerror=\"this.remove()\">':'')+'<span>'+esc(initial(name))+'</span></span>';}\nfunction when(m){const d=new Date(m.date);return Number.isNaN(d.getTime())?'Ώρα μη διαθέσιμη':fmtDate.format(d)+' · '+fmtTime.format(d);}\nfunction score(m){return num(m.home_score)!==null&&num(m.away_score)!==null&&(isLive(m)||isDone(m))?m.home_score+' – '+m.away_score:'VS';}\nfunction market(label,n){return '<div class=\"odd-row\"><div class=\"odd-values\"><span>'+esc(label)+'</span><b>'+pct(n)+'</b></div><div class=\"prob-bar\"><span style=\"width:'+Math.max(0,Math.min(100,Number(n)||0))+'%\"></span></div></div>';}\nfunction markets(m){\n const p=m.model;\n if(!p)return '<div class=\"unavailable\"><strong>Πρόβλεψη μη διαθέσιμη</strong>Δεν υπάρχουν αρκετά αξιόπιστα δεδομένα βαθμολογίας για τις δύο ομάδες. Δεν εμφανίζουμε τυχαία ποσοστά.<p class=\"market-caption\">Οι εκτιμήσεις προστίθενται αυτόματα όταν το δείγμα επαρκεί.</p></div>';\n const vals=[p.p1,p.px,p.p2],best=vals.indexOf(Math.max(...vals));\n return '<div class=\"side-label\">ΥΠΟΛΟΓΙΣΜΕΝΕΣ ΠΙΘΑΝΟΤΗΤΕΣ</div><div class=\"triple\">'+['1','Χ','2'].map((n,i)=>'<div'+(i===best?' class=\"best\"':'')+'><small>'+n+'</small><b>'+pct(vals[i])+'</b></div>').join('')+'</div><div class=\"other-markets\"><div><small>OVER 2.5</small><b>'+pct(p.over25)+'</b></div><div><small>GG / BTTS</small><b>'+pct(p.btts)+'</b></div></div>'+\n '<p class=\"model-note\">Προσωρινό Poisson από πραγματικά ιστορικά αποτελέσματα ή βαθμολογίες SportAPI.ai. Χαμηλή βεβαιότητα: χωρίς επικυρωμένο backtest. Πρόβλεψη πριν τον αγώνα — όχι in-play πιθανότητα.</p>';\n}\nfunction featured(m){\n if(!m){$('featuredContent').innerHTML='<div class=\"loading\">Δεν υπάρχουν διαθέσιμοι αγώνες αυτή τη στιγμή. <a href=\"/data\" class=\"feat-details\">Δες το πρόγραμμα →</a></div>';return;}\n $('featuredContent').innerHTML='<div class=\"feature-top\"><b>'+esc(m.league)+'</b><span>'+(isLive(m)?'● LIVE':isDone(m)?'ΤΕΛΙΚΟ':'ΕΠΟΜΕΝΟΣ ΑΓΩΝΑΣ')+' · '+esc(when(m))+'</span></div>'+\n '<div class=\"feature-grid\"><div class=\"feature-main\"><div class=\"featured-teams\"><div class=\"ft-team\">'+crest(m,'home')+'<b>'+esc(m.home)+'</b></div><div class=\"vs\"><strong>'+esc(score(m))+'</strong>'+(isLive(m)?'LIVE':'FOOTBALL')+'</div><div class=\"ft-team\">'+crest(m,'away')+'<b>'+esc(m.away)+'</b></div></div><div class=\"feat-bottom\"><span class=\"f-league\"><span class=\"league-icon\">TD</span>'+esc(m.league)+'</span><a href=\"/data\" class=\"feat-details\">Πλήρη στοιχεία αγώνα →</a></div></div><aside class=\"feature-side\">'+markets(m)+'</aside></div>';\n $('featuredContent').setAttribute('aria-busy','false');\n}\nfunction upcoming(matches){\n const wrap=$('upcomingGrid'),items=Array.isArray(matches)?matches.slice(0,3):[];\n if(!items.length){wrap.innerHTML='<div class=\"loading\">Δεν υπάρχουν άλλοι επιλεγμένοι αγώνες. <a href=\"/data\">Δες το πλήρες πρόγραμμα →</a></div>';}\n else wrap.innerHTML=items.map(m=>'<article class=\"upcoming-card\"><div class=\"up-meta\"><span>'+esc(m.league)+'</span><span>'+esc(when(m))+'</span></div><div class=\"up-match\"><div class=\"up-team\">'+crest(m,'home')+'<b>'+esc(m.home)+'</b></div><span class=\"up-versus\">'+esc(score(m))+'</span><div class=\"up-team\">'+crest(m,'away')+'<b>'+esc(m.away)+'</b></div></div><div class=\"up-footer\"><span>'+(m.model?'1 '+pct(m.model.p1)+' · Χ '+pct(m.model.px)+' · 2 '+pct(m.model.p2):'Πρόβλεψη μη διαθέσιμη')+'</span><a href=\"/data\">Στοιχεία ↗</a></div></article>').join('');\n wrap.setAttribute('aria-busy','false');\n}\nlet controller=null,fetching=false;\nasync function load(){\n if(fetching)return;fetching=true;controller=new AbortController();\n try{\n  const res=await fetch('/api/home-v23',{signal:controller.signal,headers:{Accept:'application/json'},cache:'no-store'});\n  if(!res.ok)throw new Error(res.status===429?'quota':'feed');\n  const data=await res.json();if(data.source!=='SportAPI.ai')throw Error('wrong_source');\n  $('metricMatches').textContent=String(data.coverage?.matches??'—');\n  $('metricLeagues').textContent=String(data.coverage?.competitions??'—');\n  featured(data.featured);upcoming(data.upcoming);\n  const t=new Date(data.updated_at);\n  $('refreshStatus').textContent='SportAPI.ai · Ενημερώθηκε '+(Number.isNaN(t.getTime())?'πρόσφατα':fmtTime.format(t));\n }catch{\n  $('featuredContent').innerHTML='<div class=\"loading\">Η πηγή SportAPI.ai δεν είναι διαθέσιμη αυτή τη στιγμή. Δοκιμάστε ξανά αργότερα.</div>';\n  $('featuredContent').setAttribute('aria-busy','false');\n  $('upcomingGrid').innerHTML='<div class=\"loading\">Δεν μπορέσαμε να φορτώσουμε τους αγώνες.</div>';\n  $('upcomingGrid').setAttribute('aria-busy','false');\n  $('refreshStatus').textContent='Η ενημέρωση δεν είναι διαθέσιμη';\n }finally{fetching=false;}\n}\n$('year').textContent=String(new Date().getFullYear());\nvoid load();\nsetInterval(()=>{if(!document.hidden)void load()},180000);\n})();";
/* Authenticated logo streaming from SportAPI.ai only.
 * Tokens are HMAC links to IDs present in a public fixture response.
 * Never expose Cloudflare SPORTAPI_AI_KEY to users or GitHub.
 */
const tdLogoId=s=>/^\d{1,13}$/.test(String(s??''))?String(s):null;
async function tdLogoKey(secret){return crypto.subtle.importKey('raw',new TextEncoder().encode('tiki-logo-v1:'+secret),{name:'HMAC',hash:'SHA-256'},false,['sign','verify']);}
async function tdSignedLogo(secret,id){id=tdLogoId(id);if(!id)return null;const key=await tdLogoKey(secret);const bytes=new Uint8Array(await crypto.subtle.sign('HMAC',key,new TextEncoder().encode('sportapi-team:'+id)));const hex=Array.from(bytes,b=>b.toString(16).padStart(2,'0')).join('');return '/api/logo/team/'+id+'?sig='+hex;}
async function tdServeLogo(req,env,ctx,url){
 const id=tdLogoId(url.pathname.split('/').at(-1)),sig=url.searchParams.get('sig');
 if(!id||!sig||!/^[0-9a-f]{64}$/.test(sig)||!env?.SPORTAPI_AI_KEY)return new Response('Not Found',{status:404});
 const key=await tdLogoKey(env.SPORTAPI_AI_KEY);const raw=new Uint8Array(sig.match(/../g).map(x=>parseInt(x,16)));
 if(!await crypto.subtle.verify('HMAC',key,raw,new TextEncoder().encode('sportapi-team:'+id)))return new Response('Forbidden',{status:403});
 const cacheReq=new Request('https://tiki-logo-cache.local/team/'+id);
 try{const cached=await caches.default.match(cacheReq);if(cached)return cached;}catch{}
 const c=new AbortController(),timer=setTimeout(()=>c.abort(),6500);
 try{
  const r=await fetch('https://sportapi.ai/api/teams/'+id+'/logo',{headers:{'X-Api-Key':env.SPORTAPI_AI_KEY,Accept:'image/png,image/webp,image/jpeg,image/svg+xml'},redirect:'manual',signal:c.signal});
  if(!r.ok)return new Response('Image unavailable',{status:r.status===429?429:404,headers:{'Cache-Control':'no-store'}});
  const type=(r.headers.get('content-type')||'').split(';')[0].toLowerCase();
  const allowed=['image/png','image/jpeg','image/webp','image/svg+xml'];
  if(!allowed.includes(type)||Number(r.headers.get('content-length')||0)>260000)return new Response('Unsupported image',{status:415});
  const bytes=await r.arrayBuffer();if(bytes.byteLength>260000||bytes.byteLength<32)return new Response('Invalid image',{status:415});
  const h=new Headers({'Content-Type':type,'Cache-Control':'public,max-age=86400','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; sandbox"});
  const response=new Response(bytes,{status:200,headers:h});try{ctx?.waitUntil?.(caches.default.put(cacheReq,response.clone()))}catch{}
  return response;
 }catch{return new Response('Logo temporarily unavailable',{status:503});}finally{clearTimeout(timer)}
}

